      en: ["Designated as a UNESCO Biosphere Reserve in 1982.", "Daecheongbong is the highest point in the park at 1,708 meters.", "Home to the 7th-century Sinheungsa Temple.", "The bronze 'Jwabul' Buddha statue is 14.6 meters tall.", "Over 1,000 plant species are documented within the park.", "The cable car to Gwongeumseong has been in operation since 1971."],
      es: ["Número de senderos: más de 20", "Teleférico: altura 800 m", "Cumbre más alta: Daecheongbong (1.708 m)", "Especies animales: goral coreano, ardilla voladora", "Especies de plantas: más de 1.000", "Templo más antiguo: Baekdam (647)"],
      pt: ["Número de trilhas: mais de 20", "Teleférico: altura 800 m", "Cume mais alto: Daecheongbong (1.708 m)", "Espécies animais: goral coreano, esquilo-voador", "Espécies de plantas: mais de 1.000", "Templo mais antigo: Baekdam (647)"],
      fr: ["Nombre de sentiers : plus de 20", "Téléphérique : hauteur 800 m", "Plus haut sommet : Daecheongbong (1 708 m)", "Espèces animales : goral coréen, écureuil volant", "Espèces de plantes : plus de 1 000", "Plus ancien temple : Baekdam (647)"],
