      en: "The largest and oldest tea plantations in South Korea, known for their terraced fields and high-quality green tea.",
      es: "Las plantaciones de té más grandes y antiguas de Corea del Sur, conocidas por sus campos en terrazas y su té verde de alta calidad.",
