      ro: ["Fondată simbolic drept Republica Naminara la 1 martie 2006.", "Insula are o circumferință de aproximativ 5 kilometri.", "Poartă numele generalului Nami, al cărui mormânt se află pe insulă.", "Peste 3 milioane de turiști vizitează insula în fiecare an.", "Găzduiește Muzeul Song, care expune instrumente muzicale globale.", "Celebra alee de metasequoia a fost plantată în anii 1970."],
