      ro: ["Desemnat UNESCO Creative City of Crafts în anul 2010.", "Găzduiește peste 300 de ateliere active de ceramică.", "Tradiția datează de peste 600 de ani, din dinastia Joseon.", "Festivalul de Ceramică Icheon atrage anual peste 1 mil. de vizitatori.", "Produce celebrele tipuri de ceramică celadon și baekja.", "Produsele ceramice din Icheon sunt exportate în peste 30 de țări."],
      en: ["Named a UNESCO Creative City of Crafts and Folk Art in 2010.", "Home to more than 300 active pottery workshops.", "The tradition dates back over 600 years to the Joseon Dynasty.", "The Icheon Ceramics Festival welcomes over 1 million visitors annually.", "Specializes in the production of celadon and white porcelain (baekja).", "Pottery products from Icheon are exported to over 30 countries globally."],
      es: ["Talleres: más de 300", "Galerías: 50", "Visitantes del festival: más de 1 millón", "Países de exportación: más de 30", "Época histórica: Dinastía Joseon (1392-1910)", "Tipos de cerámica propios: Celadón y Baekja"],
      pt: ["Oficinas: mais de 300", "Galerias: 50", "Visitantes do festival: mais de 1 milhão", "Países de exportação: mais de 30", "Época histórica: Dinastia Joseon (1392-1910)", "Tipos de cerâmica próprios: Celadon e Baekja"],
      fr: ["Ateliers : plus de 300", "Galeries : 50", "Visiteurs du festival : plus d'un million", "Pays d'exportation : plus de 30", "Époque historique : Dynastie Joseon (1392-1910)", "Types de poterie propres : Céladon et Baekja"],
