    description: {
      de: "Ein jährliches Festival, das die reiche landwirtschaftliche Tradition Koreas feiert und in der größten Reisanbauregion des Landes stattfindet.",
      hu: "Éves fesztivál, amely Korea gazdag mezőgazdasági hagyományait ünnepli az ország legnagyobb rizstermő vidékén.",
      ro: "Un festival anual care celebrează bogata tradiție agricolă a Coreei, desfășurat în cea mai mare regiune cultivatoare de orez din țară.",
      en: "An annual festival celebrating Korea's rich agricultural heritage, held in the country's largest rice-growing region.",
      es: "Un festival anual que celebra la rica tradición agrícola de Corea, celebrado en la mayor región productora de arroz del país.",
      pt: "Um festival anual que celebra a rica tradição agrícola da Coreia, realizado na maior região produtora de arroz do país.",
      fr: "Un festival annuel célébrant la riche tradition agricole de la Corée, organisé dans la plus grande région rizicole du pays.",
    },
